<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import Portrait from './Portrait.vue'
import CastPicker from './CastPicker.vue'
import VideoStudio from './VideoStudio.vue'
type Row=Record<string,any>
const props=defineProps<{project:Row;sceneId:string;unitId:string;instruction:string}>()
const emit=defineEmits(['update:sceneId','update:unitId','update:instruction','save','generate','draft','audit','replace','busy'])
const mode=ref<'script'|'boards'|'video'>('script'),panel=ref(''),tools=ref(false)
const scene=computed<Row|undefined>(()=>props.project.scenes.find((s:Row)=>s.id===props.sceneId)||props.project.scenes[0])
const index=computed(()=>props.project.scenes.indexOf(scene.value))
const unit=computed<Row|undefined>(()=>scene.value?.units.find((u:Row)=>u.id===props.unitId))
const labels:Row={supported:'有依据',inference:'推测',fiction:'创作补充'},kinds:Row={event:'事件',action:'动作',dialogue:'对白',clue:'线索'}
function person(cid:string){return props.project.characters.find((c:Row)=>c.id===cid)}
function box(cid:string){return props.project.annotations.find((a:Row)=>a.kind==='character'&&a.characterId===cid)}
function choose(id:string){emit('update:sceneId',id);emit('update:unitId','');panel.value='';tools.value=false}
function open(u:Row,section:string){emit('update:unitId',u.id);panel.value=props.unitId===u.id&&panel.value===section?'':section}
function changed(u:Row){u.status='pending'}
function addRef(u:Row){u.references.push({sourceId:'',sourceVersion:1,annotationId:'',quote:''});changed(u)}
function refChanged(r:Row,u:Row){r.sourceVersion=props.project.sources.find((s:Row)=>s.id===r.sourceId)?.version||1;r.annotationId='';changed(u)}
function move(n:number){const s=props.project.scenes[index.value+n];if(s)choose(s.id)}
watch(()=>props.project.id,()=>{panel.value='';mode.value='script'})
</script>
<template>
<section class="script-workspace">
 <div class="studio-heading"><div><small>SCRIPT & STORYBOARD</small><h2>让画中故事，徐徐展开</h2><p>逐场打磨台词与动作，再把文字转成可演绎的镜头。</p></div><button @click="emit('save')">保存修改</button></div>
 <div class="studio-layout"><aside class="studio-directory"><div><h3>场景目录</h3><small>{{project.scenes.length}} 场</small></div><div class="studio-scenes" aria-label="选择剧本场景"><button v-for="(s,i) in project.scenes" :key="s.id" :aria-pressed="scene?.id===s.id" :class="{active:scene?.id===s.id}" @click="choose(s.id)"><i>{{String(Number(i)+1).padStart(2,'0')}}</i><span>{{s.title}}<small>{{s.units.length}} 段剧本 · {{s.units.filter((u:Row)=>u.status==='approved').length}} 段已核对</small></span></button></div></aside>
 <div v-if="scene" class="studio-page"><div class="studio-scene-title"><small>第 {{String(index+1).padStart(2,'0')}} 幕 / {{String(project.scenes.length).padStart(2,'0')}}</small><h3>{{scene.title}}</h3><details><summary>本场目标与衔接</summary><p>{{scene.goal}}</p><p>{{scene.connection}}</p></details></div>
 <div class="studio-tabs" role="tablist" aria-label="剧本制作步骤"><button v-for="(label,key) in {script:'01 场景剧本',boards:'02 镜头分镜',video:'03 古画动画'}" :key="key" role="tab" :aria-selected="mode===key" :class="{active:mode===key}" @click="mode=key">{{label}}</button></div>
 <div v-if="mode==='script'" class="script-reading" role="tabpanel" aria-label="场景剧本"><div class="script-reading-top"><span>本场剧本 <small>{{scene.units.length}} 段</small></span><button @click="tools=!tools">AI 修改建议 {{tools?'−':'＋'}}</button></div>
 <div v-if="tools" class="script-ai-tools"><label>希望怎样修改<textarea :value="instruction" @input="emit('update:instruction',($event.target as HTMLTextAreaElement).value)" placeholder="例如：缩短对白、减少心理推测，让动作更克制……"/></label><div class="actions"><button @click="emit('generate','rewrite')">重写本场</button><button :disabled="!unit||unit.locked" @click="emit('generate','rewrite',unit?.id)">重写选中段落</button><button :disabled="!scene.units.length" @click="emit('generate','classify')">建议依据分类</button></div><small>生成修改提案后，可以比较内容再决定是否采用。</small></div>
 <div v-if="!scene.units.length" class="studio-empty"><h3>这一幕，等待落笔</h3><p>根据大纲生成剧本初稿，再逐段修改。</p><button class="primary" @click="emit('draft')">生成剧本初稿</button></div>
 <div v-for="(u,i) in scene.units" :key="u.id" class="script-passage" :class="{chosen:unitId===u.id,dialogue:u.kind==='dialogue'}"><div class="passage-portrait"><Portrait v-if="person(u.speakerId)&&box(u.speakerId)&&project.image" :url="project.image" :box="box(u.speakerId)"/><span v-else>{{u.kind==='dialogue'?'言':u.kind==='action'?'动':u.kind==='event'?'事':'迹'}}</span></div><div class="passage-body"><div class="passage-meta"><b>{{person(u.speakerId)?.name||(u.kind==='dialogue'?'旁白':kinds[u.kind])}}</b><span>{{String(Number(i)+1).padStart(2,'0')}} · {{labels[u.category]}} · {{u.locked?'已锁定':u.status==='approved'?'已核对':u.status==='rejected'?'需修改':'待核对'}}</span></div><p class="passage-text">{{u.text}}</p><div class="passage-actions"><button @click="open(u,'edit')">{{unitId===u.id&&panel==='edit'?'收起编辑':'编辑此段'}}</button><button @click="open(u,'evidence')">依据与核对 <span>{{u.references.length}}</span></button></div>
 <div v-if="unitId===u.id&&panel==='edit'" class="passage-editor"><fieldset :disabled="u.locked"><label>内容<textarea rows="4" v-model="u.text" @input="changed(u)"/></label><label>段落类型<select v-model="u.kind" @change="changed(u)"><option v-for="(label,key) in kinds" :key="key" :value="key">{{label}}</option></select></label><label>说话 / 关联人物 <small>点击立绘选择；再次点击可设为无人物。</small></label><CastPicker :project="project" :model-value="u.speakerId?[u.speakerId]:[]" single @update:model-value="u.speakerId=$event[0]||'';changed(u)"/></fieldset><div class="actions"><button v-if="!u.locked" class="primary" @click="emit('save')">保存修改</button><button @click="u.locked=!u.locked;emit('save')">{{u.locked?'解锁并保存':'锁定并保存'}}</button><button @click="panel=''">收起</button></div></div>
 <div v-if="unitId===u.id&&panel==='evidence'" class="passage-editor"><fieldset :disabled="u.locked"><div class="evidence-top"><label>依据分类<select v-model="u.category" @change="changed(u)"><option v-for="(label,key) in labels" :key="key" :value="key">{{label}}</option></select></label></div><label>推导过程 / 创作用途<textarea v-model="u.rationale" rows="3" @input="changed(u)"/></label><div v-for="(r,ri) in u.references" :key="ri" class="passage-reference"><label>关联资料<select v-model="r.sourceId" @change="refChanged(r,u)"><option value="">画面观察 / 未关联</option><option v-for="s in project.sources" :key="s.id" :value="s.id">{{s.title}} · v{{s.version}}</option></select></label><label v-if="!r.sourceId">已确认观察<select v-model="r.annotationId" @change="changed(u)"><option value="">请选择观察</option><option v-for="a in project.annotations.filter((a:Row)=>a.confirmed)" :key="a.id" :value="a.id">{{a.description}}</option></select></label><label>引用原文<textarea v-model="r.quote" @input="changed(u)"/></label><details v-if="r.sourceId"><summary>阅读完整资料</summary><p class="reference-full">{{project.sources.find((s:Row)=>s.id===r.sourceId)?.text}}</p></details><button @click="u.references.splice(ri,1);changed(u)">移除此条依据</button></div><button @click="addRef(u)">＋ 添加依据</button></fieldset><div class="actions"><button class="primary" @click="emit('audit','approved')">核对通过</button><button @click="emit('audit','rejected')">标记需修改</button><button @click="emit('audit','pending')">稍后核对</button></div></div>
 </div></div></div>
 <VideoStudio v-else :project="project" :scene-id="scene.id" :view="mode" @replace="emit('replace',$event)" @busy="emit('busy',$event)"/>
 <div class="studio-pagination"><button :disabled="index===0" @click="move(-1)">← 上一幕</button><span>{{index+1}} / {{project.scenes.length}}</span><button :disabled="index===project.scenes.length-1" @click="move(1)">下一幕 →</button></div>
 </div><div v-else class="studio-empty">请先完成故事大纲。</div></div>
</section>
</template>
<style scoped>
