ing{padding:24px 32px}.script-reading-top{display:flex;align-items:center;justify-content:space-between;margin-bottom:15px;font-size:13px}.script-reading-top small{display:inline;margin-left:10px}.script-reading-top button{background:transparent;border:0;font-size:11px;color:#829374;padding:8px 0}.script-passage{display:flex;gap:18px;padding:24px 0;border-bottom:1px solid #edf0e5}.passage-portrait{flex:0 0 52px;padding-top:2px}.passage-portrait :deep(canvas){width:50px;height:72px;object-fit:contain;background:#eeeedd}.passage-portrait>span{display:block;width:42px;height:42px;text-align:center;border:1px solid #dde5d2;border-radius:50%;background:#f4f6ed;font:18px/40px serif;color:#91a180}.passage-body{min-width:0;flex:1}.passage-meta{display:flex;justify-content:space-between;align-items:center;gap:15px}.passage-meta b{font-size:12px;font-weight:500}.passage-meta>span{font-size:10px;color:#96a18a}.passage-text{font-size:14px;line-height:2.05;white-space:pre-wrap;margin:12px 0 10px;color:#3a4e37}.dialogue .passage-text{font-family:serif;font-size:17px}.passage-actions{display:flex;gap:18px}.passage-actions button{padding:5px 0;font-size:10px;background:transparent;border:0;color:#8d9b7e}.passage-actions button:hover{color:#385d30}.passage-actions span{margin-left:4px}.chosen .passage-actions button{color:#527644}.passage-editor{background:#f5f7ed;border:1px solid #e0e7d5;border-radius:7px;padding:20px;margin-top:14px}.passage-editor label{font-size:11px;margin:10px 0}.passage-editor :is(input,select,textarea){font-size:12px}.passage-editor textarea{line-height:1.9}.passage-editor label small{margin:7px 0 12px;font-size:10px}.passage-editor .actions{margin-top:16px}.passage-editor button{font-size:11px}.passage-reference{padding:14px;margin:14px 0;background:#fffef9;border:1px solid #e0e6d6;border-radius:6px}.passage-reference details{font-size:11px;margin:12px 0}.reference-full{white-space:pre-wrap;max-height:280px;overflow:auto;font-size:12px;line-height:1.9}.scri